window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-25701\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακροβιότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 122 na letra μ · nº geral 25701</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. longevidade. 〈μακρόβιος〉</p></section></article>\n<article id=\"entry-dgp-25702\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακροβίοτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 123 na letra μ · nº geral 25702</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">μακρόβιος.</p></section></article>\n<article id=\"entry-dgp-25703\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακρόθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 124 na letra μ · nº geral 25703</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv., tard. 1 de longe 2 desde longo tempo. 〈μακρός, -θεν〉</p></section></article>\n<article id=\"entry-dgp-25704\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακροθυμέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 125 na letra μ · nº geral 25704</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. 1 ser magnânimo, tolerante com alguém, ἐπί e dat. 2 ser perseverante; ter pertinácia. 〈μα­κρός, θυμός〉</p></section></article>\n<article id=\"entry-dgp-25705\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακροθυμία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 126 na letra μ · nº geral 25705</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 magnanimidade; tolerância 2 perseverança; pertinácia. 〈μακρός, θυμός〉</p></section></article>\n<article id=\"entry-dgp-25706\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακροθύμως</h1><div class=\"entry-meta\"><span>DGP · ordem 127 na letra μ · nº geral 25706</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv., bíbl. com magnanimidade; com tolerância.</p></section></article>\n<article id=\"entry-dgp-25707\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακρόκωλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 128 na letra μ · nº geral 25707</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de pernas compridas 2 de ramos compridos (árvore) 3 de membros longos (período oratório). 〈μακρός, κῶλον〉</p></section></article>\n<article id=\"entry-dgp-25708\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακρολογέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 129 na letra μ · nº geral 25708</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 falar longamente 2 dizer algo, ac., em muitas palavras; falar prolixamente.</p></section></article>\n<article id=\"entry-dgp-25709\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακροπονία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 130 na letra μ · nº geral 25709</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">esforço prolongado. 〈μακρός, πόνος〉</p></section></article>\n<article id=\"entry-dgp-25710\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακρός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 131 na letra μ · nº geral 25710</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(comp. μακρότερος ou μάσσων, superl. μακρότατος ou μήκιστος)</p></section></article>\n<article id=\"entry-dgp-25711\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 132⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 132 na letra μ · nº geral 25711</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 (dimensão) longo; grande; comprido; alongado; alto; elevado; profundo</p></section></article>\n<article id=\"entry-dgp-25712\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 133⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 133 na letra μ · nº geral 25712</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2 (distância) distante; afastado; levado para longe</p></section></article>\n<article id=\"entry-dgp-25713\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 134⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 134 na letra μ · nº geral 25713</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3 (tempo) longo; prolongado; que dura muito; distante no tempo</p></section></article>\n<article id=\"entry-dgp-25714\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 135⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 135 na letra μ · nº geral 25714</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">4 Métr. longo metricamente</p></section></article>\n<article id=\"entry-dgp-25715\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 136⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 136 na letra μ · nº geral 25715</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">5 (quantidade) grande; considerável; abundante; μα­κρῷ com comp. ou superl. muito; abundantemente</p></section></article>\n<article id=\"entry-dgp-25716\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 137⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 137 na letra μ · nº geral 25716</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">6 adv. μακρά, μακρόν longamente; μακρότερον mais lon­gamente</p></section></article>\n<article id=\"entry-dgp-25717\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 138⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 138 na letra μ · nº geral 25717</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">7 loc. adv. διὰ μακροῦ durante muito tempo; muito tempo depois, διὰ μακροῦ longe, διὰ μακρῶν longamente, διὰ μακρᾶς depois de um longo tempo, ἐπὶ μα­κρόν por um longo intervalo de tempo, οὐκ ἐς μα­κρόν pínd. não por muito tempo, ἐς τὰ μακρότατα tuc. no ponto mais elevado</p></section></article>\n<article id=\"entry-dgp-25718\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">1 μακρὸν ἔγχος</h1><div class=\"entry-meta\"><span>DGP · ordem 139 na letra μ · nº geral 25718</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">hom. lança comprida, οὔρεα μακρά hom. elevadas montanhas, μακρὸς Ὄλυμπος hom. o alto Olimpo, φρείατα μακρά hom. poços profundos, μακρὸς καὶ ὄρθιος οἶμος ἐς αὐτήν hes. longo e árduo é o caminho até ela, τὰ μακρὰ τείχη ᾠκοδόμησαν tuc. construíram as altas muralhas, ὁδὸν μακρὰν ἥκων δείπνει ἤδη xen. chegando de longo caminho, agora janta, μακρὸν πλοῖον διαφυγόντες dem. fugitivos de um navio longo, i.e., de navio de guerra</p></section></article>\n<article id=\"entry-dgp-25719\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">2 ναυτιλίῃσι μακρῇσι ἐπιθέσθαι</h1><div class=\"entry-meta\"><span>DGP · ordem 140 na letra μ · nº geral 25719</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">her. entregar-se a navegações distantes, τὴν μακρὰν ἀποικίαν ésql. uma colonização distante, καὶ μακροὺς ὄντας ἐν πορείᾳ καὶ διαλελυμένους pol. estando, durante a caminhada, afastados um dos outros e fora do alinhamento, ἴχνη τοῦ λαγὼ μακρά ἐστι xen. os rastros da lebre são extensos</p></section></article>\n<article id=\"entry-dgp-25720\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">3 ἤματα μακρὰ πέλονται</h1><div class=\"entry-meta\"><span>DGP · ordem 141 na letra μ · nº geral 25720</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">hom. os dias são longos, μακρὸν ἐέλδωρ hom. um desejo antigo, ἐμοὶ μακρὸν ἀναγήσασθαι pínd. narrá-(lo) seria longo para mim, χρόνῳ μακρῷ ou ἐν χρόνῳ μακρῷ durante muito tempo, μακρὸν ἂν εἴη γράφειν xen. seria longo descrever, μῶν μὴ μακρὸς ὁ λόγος; plat. será que o discurso não será longo? ἅτε μακρῶν τῶν νυκτῶν οὐσῶν plat. já que as noites eram longas, μακροῖς λόγοις καὶ κατηγορίαις προσέχειν dem. estar atento aos longos discursos e acusações</p></section></article>\n<article id=\"entry-dgp-25721\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">4 μακρὰ συλλαβή</h1><div class=\"entry-meta\"><span>DGP · ordem 142 na letra μ · nº geral 25721</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">artt. sílaba longa</p></section></article>\n<article id=\"entry-dgp-25722\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">5 μακρὸν δὲ πῆμα ξυντόμως ἐφημίσω</h1><div class=\"entry-meta\"><span>DGP · ordem 143 na letra μ · nº geral 25722</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ésql. disseste concisamente um sofrimento enorme, μακρὰ οὐσία artt. grande riqueza, τοῖς μὲν ἐπὶ μακρὸν πορευομένοις μακραὶ καὶ αἱ ἐπιβοήθειαι xen. aos que faziam longas caminhadas também de longe vinham os socorros, μακρῷ ἄριστος her. de longe, o melhor, μακρῷ πρῶτος her. de longe, o primeiro, μακρῷ βέλτιον plat. em muito, o melhor</p></section></article>\n<article id=\"entry-dgp-25723\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">6 μακρὰ βιβάς</h1><div class=\"entry-meta\"><span>DGP · ordem 144 na letra μ · nº geral 25723</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ou βιβῶν ou βιβάσθων hom. a passos largos, μακρὰ βοᾶν hom. gritar forte, μακρὰ κλάειν ar. chorar alto, μακρὰ χαίρειν φράζω luc. digo um grande adeus, βούλομαι δ’ ὀλίγῳ μακρότερα περὶ τοῖν πολέοιν εἰπεῖν isócr. quero falar um pouco mais acerca das duas cidades</p></section></article>\n<article id=\"entry-dgp-25724\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">7 διὰ μακροτέρων ἐπαινεῖν</h1><div class=\"entry-meta\"><span>DGP · ordem 145 na letra μ · nº geral 25724</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">isócr. elogiar mais longamente, φοβούμενοι μὴ καὶ ἐπὶ μακρότερον σφίσι τι νεωτερισθῇ tuc. temendo que também lhes ocorresse uma tentativa</p></section></article>\n<article id=\"entry-dgp-25725\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 146⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 146 na letra μ · nº geral 25725</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de inovação política muito grande, ἥξει οὐ διὰ μακροῦ plat. virá sem demora, ἐὰν θεὸς θέλῃ, ἀμυνούμεθα τοὺς πολεμίους οὐκ εἰς μακράν xen. se o deus desejar, puniremos os inimigos sem demora.</p></section></article>\n<article id=\"entry-dgp-25726\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακρότατος</h1><div class=\"entry-meta\"><span>DGP · ordem 147 na letra μ · nº geral 25726</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">superl. de μακρός.</p></section></article>\n<article id=\"entry-dgp-25727\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακροτάτω</h1><div class=\"entry-meta\"><span>DGP · ordem 148 na letra μ · nº geral 25727</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. superl. tard. muito longe.</p></section></article>\n<article id=\"entry-dgp-25728\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακρότερος</h1><div class=\"entry-meta\"><span>DGP · ordem 149 na letra μ · nº geral 25728</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. μακρός.</p></section></article>\n<article id=\"entry-dgp-25729\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακροτέρω</h1><div class=\"entry-meta\"><span>DGP · ordem 150 na letra μ · nº geral 25729</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. comp. mais longe.</p></section></article>\n<article id=\"entry-dgp-25730\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακροτέρως</h1><div class=\"entry-meta\"><span>DGP · ordem 151 na letra μ · nº geral 25730</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. por mais longo tempo.</p></section></article>\n<article id=\"entry-dgp-25731\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακρότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 152 na letra μ · nº geral 25731</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comprimento. 〈μακρός〉</p></section></article>\n<article id=\"entry-dgp-25732\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακρόχειρ, χειρος</h1><div class=\"entry-meta\"><span>DGP · ordem 153 na letra μ · nº geral 25732</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) de longas mãos, epít. de Artaxerxes. 〈μακρός, χείρ〉</p></section></article>\n<article id=\"entry-dgp-25733\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακροχρόνιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 154 na letra μ · nº geral 25733</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de longa duração; duradouro 2 de longa vida. 〈μακρός, χρόνος〉</p></section></article>\n<article id=\"entry-dgp-25734\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μάκρων, ωνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 155 na letra μ · nº geral 25734</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Macron, n. de homem ♦ οἱ Μάκρονες 2 os Cabeças-grandes, povo do Ponto Euxino. 〈μακρός〉</p></section></article>\n<article id=\"entry-dgp-25735\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακρῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 156 na letra μ · nº geral 25735</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 longamente 2 Pros. com vogal longa 3 len­tamente 4 por um longo tempo.</p></section></article>\n<article id=\"entry-dgp-25736\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακτήριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 157 na letra μ · nº geral 25736</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gamela para fazer massas. 〈μάσσω〉</p></section></article>\n<article id=\"entry-dgp-25737\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μάκτρα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 158 na letra μ · nº geral 25737</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 gamela para massas 2 almofariz para amassar. 〈μάσσω〉</p></section></article>\n<article id=\"entry-dgp-25738\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 159 na letra μ · nº geral 25738</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = μηκύνω.</p></section></article>\n<article id=\"entry-dgp-25739\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακών</h1><div class=\"entry-meta\"><span>DGP · ordem 160 na letra μ · nº geral 25739</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor. de μηκάομαι.</p></section></article>\n<article id=\"entry-dgp-25740\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μάκων</h1><div class=\"entry-meta\"><span>DGP · ordem 161 na letra μ · nº geral 25740</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = μήκων.</p></section></article>\n<article id=\"entry-dgp-25741\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μάλα</h1><div class=\"entry-meta\"><span>DGP · ordem 162 na letra μ · nº geral 25741</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. (comp. μᾶλλον, superl. μάλιστα)</p></section></article>\n<article id=\"entry-dgp-25742\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 163⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 163 na letra μ · nº geral 25742</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 muito; bastante; fortemente; inteiramente; completamente; plenamente; verdadeiramente, junto de adj., adv. ou partíc., esp. em uma resposta</p></section></article>\n<article id=\"entry-dgp-25743\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 164⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 164 na letra μ · nº geral 25743</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2 junto de verbo, de verdade; mesmo; bem; a valer; de bom grado</p></section></article>\n<article id=\"entry-dgp-25744\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 165⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 165 na letra μ · nº geral 25744</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3 junto de conj. cond. εἰ μάλα, εἰ καὶ μάλα, καὶ εἰ μάλα, εἰ καὶ μάλα περ com ind., já que; com opt., se bem que; ainda que; mesmo se</p></section></article>\n<article id=\"entry-dgp-25745\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μᾶλλον</h1><div class=\"entry-meta\"><span>DGP · ordem 166 na letra μ · nº geral 25745</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comp.</p></section></article>\n<article id=\"entry-dgp-25746\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 167⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 167 na letra μ · nº geral 25746</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">4 junto de verbo, mais; antes, podendo ser reforçado por πολύ ou πολλῳ muito, ἔτι ainda, καὶ ἔτι e ainda, com compl. no gen. ou precedido de ἤ, freq. não expresso</p></section></article>\n<article id=\"entry-dgp-25747\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 168⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 168 na letra μ · nº geral 25747</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">5 junto de adj., freq. no comp., muito</p></section></article>\n<article id=\"entry-dgp-25748\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 169⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 169 na letra μ · nº geral 25748</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">6 loc. adv. μᾶλλον δέ ou antes; ou melhor, ἐπὶ μᾶλλον cada vez mais</p></section></article>\n<article id=\"entry-dgp-25749\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μάλιστα</h1><div class=\"entry-meta\"><span>DGP · ordem 170 na letra μ · nº geral 25749</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">superl.</p></section></article>\n<article id=\"entry-dgp-25750\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 171⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 171 na letra μ · nº geral 25750</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">7 o mais; principalmente; sobretudo</p></section></article>\n<article id=\"entry-dgp-25751\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 172⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 172 na letra μ · nº geral 25751</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">8 muitíssimo; completamente; absolutamente; em respostas, certamente; absolutamente; perfeitamente</p></section></article>\n<article id=\"entry-dgp-25752\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 173⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 173 na letra μ · nº geral 25752</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">9 com num. ou n. exprimindo quantidade, pouco mais ou menos; cerca de; quase</p></section></article>\n<article id=\"entry-dgp-25753\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">1 μάλα πρότερος</h1><div class=\"entry-meta\"><span>DGP · ordem 174 na letra μ · nº geral 25753</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">hom. muito anterior, μάλα μέγας κτύπος sóf. um ruído muito grande, μάλα πολλά hom. uma quantidade muito grande, μάλα πάντες hom. todos sem exceção, μάλα δὴ πρεσβύτης xen. muito velho, εὖ μάλα xen. ou μάλ’ εὖ hom. muito bem ou absolutamente bem, εὖ μάλα παλαιόν plat. bem antigo mesmo, πάγχυ μάλα ou μάλα πάγχυ hom. completamente, μάλ’ αὐτίκα hom. ou αὐτίκα μάλα her. imediatamente, μάλ’ ἀσμένως ésql. muito prazerosamente, μάλα γε ὀψὲ ἀφικόμενος plat. tendo chegado muito tarde, ἦ μάλα, ἦ μάλα δή hom. sim, certamente, seguramente, καὶ μάλα plat. também, muito certamente, μάλα τοι xen. por certo, então, μάλα δή certamente, vamos!, μάλ’ οὐ, οὐ μάλα, μάλ’ οὔπως, οὐ μάλα τι certamente não, por certo de maneira alguma</p></section></article>\n<article id=\"entry-dgp-25754\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">2 μάλα συντεταγμένον στράτευμα</h1><div class=\"entry-meta\"><span>DGP · ordem 175 na letra μ · nº geral 25754</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">xen. tropa bem ordenada, μάλα βουλόμενος xen. desejando ardentemente, σοὶ δὲ μάλ’ ἕψομ’ ἐγώ hom. eu a ti prontamente seguirei, φεῦγε μάλα hom. foge rápido</p></section></article>\n<article id=\"entry-dgp-25755\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">3 εἰ μάλα καρτερός ἐσσι, θεός που σοὶ τό γ’ ἔδωκεν</h1><div class=\"entry-meta\"><span>DGP · ordem 176 na letra μ · nº geral 25755</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">hom. se verdadeiramente és forte, foi um deus que te deu isso, ἴση μοῖρα μένοντι καὶ εἰ μάλα τις πολεμίζοι hom. destino igual cabe ao que resiste e a alguém que peleja com vigor, μάλα περ μεμαώς hom. ainda que ardente</p></section></article>\n<article id=\"entry-dgp-25756\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">4 μᾶλλον τοῦ δέοντος</h1><div class=\"entry-meta\"><span>DGP · ordem 177 na letra μ · nº geral 25756</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dem. mais do que necessário, μᾶλλον τοῦ προσήκοντος dem. mais do que convém, τεθνάναι βού­λεσθαι μᾶλλον ἢ ζώειν her. desejar estar morto mais que viver, πάσας τὰς ἀγέλας ταύτας ἐδοκοῦμεν ὁρᾶν μᾶλλον ἐθελούσας πείθεσθαι τοῖς νομεῦσιν μᾶλλον ἢ τοὺς ἀνθρώπους τοῖς ἄρχουσι xen. parecia que víamos esses rebanhos todos bem mais dispostos a obedecer aos pastores, muito mais do que os homens aos chefes, ἐπ’ οὐδένας μᾶλλον συνίσ­τανται ἢ ἐπὶ τούτους οὓς ἄν αἴσθωνται ἄρχειν αὐτῶν ἐπιχειροῦντας xen. contra ninguém conjuraram mais do que contra os que percebiam tentar governá-los, οὐδενὸς μᾶλλον προενοεῖτο ὡς τῆς αὐτοῦ σωτηρίας pol. nada mais o preocupava senão a sua própria saúde</p></section></article>\n<article id=\"entry-dgp-25757\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">5 μᾶλλον εὐτυχέστερος</h1><div class=\"entry-meta\"><span>DGP · ordem 178 na letra μ · nº geral 25757</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">eur. muito mais feliz, οὐ γὰρ ὁ μέγα πλούσιος μᾶλλον τοῦ ἐπ’ ἡμέρην ἔχοντος ὀλβιώτερός ἐστι her. pois o muito rico não é mais feliz do que aquele que tem o de cada dia, ἥδιον εἶναι εὖ τε λέγοντα καὶ εὖ ποιοῦντα παρορμᾶν μᾶλλον ἢ λυποῦντα καὶ ἀναγκάζοντα xen. é mais agradável exortar dizendo boas palavras e fazendo bons atos do que afligindo e constrangendo</p></section></article>\n<article id=\"entry-dgp-25758\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">6 χαλεπόν, μᾶλλον δὲ ἀδύνατον εἶναι</h1><div class=\"entry-meta\"><span>DGP · ordem 179 na letra μ · nº geral 25758</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">plat. é difícil, ou melhor, impossível, ἄκουε δή, μᾶλλον δ’ ἀποκρίνου plat. escuta então, ou antes, responde, θορυβώδης ἐπὶ μᾶλλον ἀεὶ συμβαίνει γιγνόμενος plat. acontece que está sempre se tornando mais e mais barulhento</p></section></article>\n<article id=\"entry-dgp-25759\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">7 ὅσπερ εὐδοκιμεῖ μάλιστα τῶν μαθητῶν</h1><div class=\"entry-meta\"><span>DGP · ordem 180 na letra μ · nº geral 25759</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">plat. justamente aquele que, dentre os discípulos, tem a melhor reputação, μάλιστα πάντων ἀνθρώπων her. o melhor dentre todos os homens, τόξον δ’ ἄνδρεσσι μελήσει, μαλιστα δ’ ἐμοί hom. um arco interessará aos homens, sobretudo a mim, μάλιστα πάντων lit. o máximo dentre todos, i. e., absolutamente, completamente, ὡς οἶόν τε μάλιστα plat. o mais possível, ὡς μάλιστα δύναμαι plat. o máximo que eu puder</p></section></article>\n<article id=\"entry-dgp-25760\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">8 ὅ γε μὴν μάλιστα ἄν τις φοβηθείη</h1><div class=\"entry-meta\"><span>DGP · ordem 181 na letra μ · nº geral 25760</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">xen. aquele que com certeza alguém temeria mais, ἔχθιστος μάλιστα hom. absolutamente detestável, μάλιστα φίλτατος hom. queridíssimo sobretudo, em resposta καὶ μάλιστα ar. completamente; sem dúvida</p></section></article>\n<article id=\"entry-dgp-25761\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">9 πεντήκοντα μάλιστα</h1><div class=\"entry-meta\"><span>DGP · ordem 182 na letra μ · nº geral 25761</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tuc. quase cinqüenta, μάλιστα τετρακόσιοι xen. cerca de quatrocentos, μάλιστά πως ἔτει πέμπτῳ pol. de qualquer modo, aproximadamente no quinto ano, ἤμισυ μάλιστα tuc. mais ou menos a metade.</p></section></article>\n<article id=\"entry-dgp-25762\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μάλαγμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 183 na letra μ · nº geral 25762</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cataplasma emoliente 2 plastrão amortecedor de golpes; couraça. 〈μαλάσσω〉</p></section></article>\n<article id=\"entry-dgp-25763\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαλακία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 184 na letra μ · nº geral 25763</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ausência de força; flacidez; fraqueza (física e moral) 2 temperamento dócil 3 pl. gentilezas; delicadezas. 〈μαλακός〉</p></section></article>\n<article id=\"entry-dgp-25764\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαλακιάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 185 na letra μ · nº geral 25764</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ser mole, fraco, doentio 2 ser pusilânime. 〈μαλακός〉</p></section></article>\n<article id=\"entry-dgp-25765\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαλακιέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 186 na letra μ · nº geral 25765</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. = μαλακιάω.</p></section></article>\n<article id=\"entry-dgp-25766\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαλακίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 187 na letra μ · nº geral 25766</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tard. enfraquecer; debilitar ♦ méd. (aor. ἐμα­λακισάμην e ἐμαλακίσθην) 2 perder a força moral; fraquejar; envilecer: οὐδὲ πρὸς τὸν θάνατον ἐμαλακίσατο xen. nem fraquejou diante da morte 3 ser doente; ser enfermo: μαλ. τοὺς πόδας sept. ter enfermidade nos pés 4 efeminar-se 5 ser brando; ser complacente.</p></section></article>\n<article id=\"entry-dgp-25767\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαλακογνώμων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 188 na letra μ · nº geral 25767</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος de decisão maleável; sem rudeza de vontade; de caráter flexível. 〈μαλακός, γνώμη〉</p></section></article>\n<article id=\"entry-dgp-25768\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαλακός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 189 na letra μ · nº geral 25768</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 agradável de tocar; macio; suave; delicado (tapete, pele, solo) 2 que não é áspero para os sentidos; que não choca; suave; agradável; fácil (canto, olhar, vinho, clima) 3 de fala conciliadora; razoável; fácil; que não golpeia (homem, caráter) 4 pouco severo; brando (castigo) 5 sem energia; frágil; mole; sem coragem; tímido 6 efeminado (som); frouxo (estilo); fraco (raciocínio) ♦ τὰ μαλακά 7 as complacências.</p></section></article>\n<article id=\"entry-dgp-25769\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαλακότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 190 na letra μ · nº geral 25769</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ausência de vigor físico; moleza 2 brandura de caráter. 〈μαλακός〉</p></section></article>\n<article id=\"entry-dgp-25770\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαλακτήρ, ῆρος</h1><div class=\"entry-meta\"><span>DGP · ordem 191 na letra μ · nº geral 25770</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) que amolece: μαλακτῆρες χρυ­σοῦ plut. que fundem e moldam o ouro. 〈μαλάσσω〉</p></section></article>\n<article id=\"entry-dgp-25771\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαλακτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 192 na letra μ · nº geral 25771</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que tem o poder de amolecer; emoliente. 〈μαλάσσω〉</p></section></article>\n<article id=\"entry-dgp-25772\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαλακύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 193 na letra μ · nº geral 25772</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐμαλάκυνα) 1 amolecer 2 enfraquecer ♦ pas. 3 tornar-se menos duro; enfraquecer-se; abrandar. 〈μαλακός〉</p></section></article>\n<article id=\"entry-dgp-25773\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαλακῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 194 na letra μ · nº geral 25773</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 sem abalo; molemente; languidamente 2 docemente 3 sem força; sem vigor; debilmente 4 sem coragem.</p></section></article>\n<article id=\"entry-dgp-25774\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μάλαξις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 195 na letra μ · nº geral 25774</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de amolecer; amolecimento. 〈μα­λάσσω〉</p></section></article>\n<article id=\"entry-dgp-25775\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαλάσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 196 na letra μ · nº geral 25775</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. -άττω (fut. μαλάξω, aor. ἐμάλαξα; aor. pas. ἐμαλάχθην) 1 tornar menos duro; amolecer; tornar flexível, maleável (metal, pele) 2 acalmar (a cólera) 3 consolar (o que sofre). 〈μαλακός〉</p></section></article>\n<article id=\"entry-dgp-25776\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαλάχη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 197 na letra μ · nº geral 25776</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">malva, planta.</p></section></article>\n<article id=\"entry-dgp-25777\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μάλβαξ, ακος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 198 na letra μ · nº geral 25777</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. = μαλάχη.</p></section></article>\n<article id=\"entry-dgp-25778\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαλερός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 199 na letra μ · nº geral 25778</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. 1 forte; impetuoso 2 violento. 〈μάλα〉</p></section></article>\n<article id=\"entry-dgp-25779\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μάλη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 200 na letra μ · nº geral 25779</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">axila: ὑπὸ μάλης sob a axila, podendo significar sob o braço ou às ocultas.</p></section></article>\n<article id=\"entry-dgp-25780\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαλθακίζομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 201 na letra μ · nº geral 25780</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pas. (só pres. e part. aor. μαλθακισθείς) poét. = μαλακίζω.</p></section></article>\n<article id=\"entry-dgp-25781\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαλθακός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 202 na letra μ · nº geral 25781</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">μαλακός.</p></section></article>\n<article id=\"entry-dgp-25782\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαλθακῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 203 na letra μ · nº geral 25782</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 docemente 2 molemente.</p></section></article>\n<article id=\"entry-dgp-25783\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαλθάσσω</h1><div class=\"entry-meta\"><span>DGP · ordem 204 na letra μ · nº geral 25783</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐμάλθαξα; aor. pas. ἐμαλθάχθην) 1 tor­nar mole 2 Medic. laxar; soltar (o ventre) 3 acalmar; apa­ziguar; aplacar 4 flexibilizar 5 entorpecer. 〈μαλθακός〉</p></section></article>\n<article id=\"entry-dgp-25784\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μάλθη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 205 na letra μ · nº geral 25784</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cera líquida com que se revestia a tabuinha de escrever 2 espécie de goma preparada com cera e pez 3 peixe do mar de carne mole.</p></section></article>\n<article id=\"entry-dgp-25785\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μαλιακὸς κόλπος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 206 na letra μ · nº geral 25785</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">o golfo Malíaco, na Tessália, acima do desfiladeiro das Termópilas.</p></section></article>\n<article id=\"entry-dgp-25786\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μάλιστα</h1><div class=\"entry-meta\"><span>DGP · ordem 207 na letra μ · nº geral 25786</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">superl.</p></section></article>\n<article id=\"entry-dgp-25787\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 208⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 208 na letra μ · nº geral 25787</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de μάλα. μαλκίω estar entorpecido de frio.</p></section></article>\n<article id=\"entry-dgp-25788\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μἀλλά</h1><div class=\"entry-meta\"><span>DGP · ordem 209 na letra μ · nº geral 25788</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase de μὴ ἀλλά.</p></section></article>\n<article id=\"entry-dgp-25789\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μᾶλλον</h1><div class=\"entry-meta\"><span>DGP · ordem 210 na letra μ · nº geral 25789</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comp.</p></section></article>\n<article id=\"entry-dgp-25790\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 211⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 211 na letra μ · nº geral 25790</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de μάλα. μαλλός, οῦ (ὁ) 1 tufo de lã 2 lã; velo 3 tufo de cabelo 4 ca­beleira.</p></section></article>\n<article id=\"entry-dgp-25791\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαλόεις, όεντος</h1><div class=\"entry-meta\"><span>DGP · ordem 212 na letra μ · nº geral 25791</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) protetor das manadas de carneiros, epít. de Apolo. 〈μᾶλον2〉</p></section></article>\n<article id=\"entry-dgp-25792\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 213⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 213 na letra μ · nº geral 25792</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">μᾶλον1 e 2 dór. = μῆλον1 e 2.</p></section></article>\n<article id=\"entry-dgp-25793\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαλοφόρος</h1><div class=\"entry-meta\"><span>DGP · ordem 214 na letra μ · nº geral 25793</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = μηλοφόρος.</p></section></article>\n<article id=\"entry-dgp-25794\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μάμμα</h1><div class=\"entry-meta\"><span>DGP · ordem 215 na letra μ · nº geral 25794</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e μάμμη, ης (ἡ) 1 mãe; mamãe, expr. infantil 2 tard. avó 3 seio da mãe.</p></section></article>\n<article id=\"entry-dgp-25795\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαμμίδιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 216 na letra μ · nº geral 25795</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">mãezinha. 〈μάμμη〉</p></section></article>\n<article id=\"entry-dgp-25796\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαμωνᾶς, ᾶ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 217 na letra μ · nº geral 25796</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. 1 riqueza; posses ♦ ὁ Μαμωνᾶς 2 Ma­monas, person. da riqueza. [aram.]</p></section></article>\n<article id=\"entry-dgp-25797\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μάν</h1><div class=\"entry-meta\"><span>DGP · ordem 218 na letra μ · nº geral 25797</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = μήν1 e 2.</p></section></article>\n<article id=\"entry-dgp-25798\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μανασσῆς, ῆ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 219 na letra μ · nº geral 25798</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. Manasse, n. de h.</p></section></article>\n<article id=\"entry-dgp-25799\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μἀνατραπῆναι</h1><div class=\"entry-meta\"><span>DGP · ordem 220 na letra μ · nº geral 25799</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase de μὴ ἀνατραπῆναι.</p></section></article>\n<article id=\"entry-dgp-25800\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μάνδρα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 221 na letra μ · nº geral 25800</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 estábulo; cavalariça 2 tard. engaste de anel.</p></section></article>\n";
